@app.get('/api/tenants/{tenant_id}/database-dump')
def download_tenant_database_dump(
    tenant_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user)
):
    if user.tenant_id != tenant_id:
        raise HTTPException(status_code=403, detail="Unauthorized access to tenant resources")
    backup = db.query(TenantBackup).filter(TenantBackup.tenant_id == tenant_id).order_by(TenantBackup.created_at.desc()).first()
    if not backup or not os.path.exists(backup.archive_path):
        raise HTTPException(status_code=404, detail="Backup archive not available")

    return FileResponse(
        path=backup.archive_path,
        filename=f"tenant_{tenant_id}_backup.sql.gz",
        media_type="application/gzip"
    )
